sql_used.garimpa-audit-20261115.sql:
\pset tuples_only on
\pset format unaligned
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout = '10s';
SELECT json_build_object('section','context','at',now(),'day_brasilia',(now() at time zone 'America/Sao_Paulo')::date,'tenant','local','read_only',current_setting('transaction_read_only'));
SELECT json_build_object('section','browser_receipts_today','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT r.request_id,r.created_at,count(p.id)::int AS products,string_agg(distinct p.marketplace,',') AS marketplaces
 FROM garimpa.extension_capture_receipt r
 CROSS JOIN LATERAL jsonb_array_elements_text(r.result->'productIds') item(id)
 JOIN garimpa.product p ON p.tenant_id=r.tenant_id AND p.id=item.id
 WHERE r.tenant_id='local' AND r.created_at >= ('2026-11-15'::timestamp AT TIME ZONE 'America/Sao_Paulo')
 GROUP BY r.request_id,r.created_at ORDER BY r.created_at
) t;
SELECT json_build_object('section','observations_today','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT p.marketplace,o.capture_source,count(*)::int AS observations,count(distinct p.id)::int AS products,
 count(*) filter(where o.capture_run_id is null)::int AS observations_without_run,min(o.observed_at) AS first_at,max(o.observed_at) AS last_at
 FROM garimpa.price_observation o JOIN garimpa.product p ON p.tenant_id=o.tenant_id AND p.id=o.product_id
 WHERE o.tenant_id='local' AND o.observed_at >= ('2026-11-15'::timestamp AT TIME ZONE 'America/Sao_Paulo')
 GROUP BY p.marketplace,o.capture_source ORDER BY p.marketplace,o.capture_source
) t;
SELECT json_build_object('section','capture_batches','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT id,status,requested_marketplaces,started_at,finished_at,metadata->>'error' AS error,
 metadata#>>'{execution,phase}' AS phase,metadata#>>'{triage,mode}' AS triage_mode,
 ARRAY(SELECT jsonb_object_keys(metadata)) AS metadata_keys
 FROM garimpa.capture_batch WHERE tenant_id='local' ORDER BY started_at DESC LIMIT 8
) t;
SELECT json_build_object('section','run_modes_today','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT marketplace,parameters->>'captureMode' AS mode,parameters->>'purpose' AS purpose,status,
 count(*)::int AS runs,sum(items_captured)::int AS items,min(started_at) AS first_at,max(started_at) AS last_at,
 count(*) filter(where parameters->>'operationBatchId' IS NOT NULL)::int AS with_batch
 FROM garimpa.capture_run WHERE tenant_id='local' AND started_at >= ('2026-11-15'::timestamp AT TIME ZONE 'America/Sao_Paulo')
 GROUP BY marketplace,parameters->>'captureMode',parameters->>'purpose',status ORDER BY marketplace,mode,purpose,status
) t;
SELECT json_build_object('section','recent_runs','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT id,marketplace,started_at,status,items_captured,error,parameters->>'captureMode' AS mode,parameters->>'purpose' AS purpose,
 parameters->>'operationBatchId' AS batch_id,ARRAY(SELECT jsonb_object_keys(parameters)) AS parameter_keys
 FROM garimpa.capture_run WHERE tenant_id='local' ORDER BY started_at DESC LIMIT 4
) t;
SELECT json_build_object('section','attribute_jobs','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT status,count(*)::int AS jobs,count(distinct product_id)::int AS products,min(updated_at) AS oldest,max(updated_at) AS newest
 FROM garimpa.curation_attribute_job WHERE tenant_id='local' GROUP BY status ORDER BY status
) t;
SELECT json_build_object('section','assessment_coverage','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT p.marketplace,count(*)::int AS products,
 count(*) filter(where EXISTS(SELECT 1 FROM garimpa.curation_attribute_assessment a WHERE a.tenant_id=p.tenant_id AND a.product_id=p.id))::int AS assessed,
 count(*) filter(where EXISTS(SELECT 1 FROM garimpa.curation_attribute_job j WHERE j.tenant_id=p.tenant_id AND j.product_id=p.id AND j.status='reconciliation'))::int AS with_uncertain_job,
 count(*) filter(where c.status='pending')::int AS legacy_pending,
 count(*) filter(where c.status='approved')::int AS catalog_approved
 FROM garimpa.product p LEFT JOIN garimpa.product_curation c ON c.tenant_id=p.tenant_id AND c.product_id=p.id
 WHERE p.tenant_id='local' GROUP BY p.marketplace ORDER BY p.marketplace
) t;
SELECT json_build_object('section','promotion_queue','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT p.marketplace,r.status,r.reason,r.result->>'reason' AS result_reason,count(*)::int AS requests,
 count(*) filter(where r.deadline>now())::int AS within_deadline,min(r.next_attempt_at) AS next_attempt_at
 FROM garimpa.curation_promotion r JOIN garimpa.product p ON p.tenant_id=r.tenant_id AND p.id=r.product_id
 WHERE r.tenant_id='local' AND r.status IN ('pending','claimed') GROUP BY p.marketplace,r.status,r.reason,r.result->>'reason'
 ORDER BY p.marketplace,r.status,r.reason
) t;
SELECT json_build_object('section','legacy_triage','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT status,count(*)::int AS runs,max(started_at) AS latest_started,max(finished_at) AS latest_finished
 FROM garimpa.triage_run WHERE tenant_id='local' GROUP BY status ORDER BY status
) t;
SELECT json_build_object('section','channels','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT channel,enabled,valid_until FROM garimpa.recommendation_channel WHERE tenant_id='local' ORDER BY channel
) t;
COMMIT;

sql_used.garimpa-audit-detail-20261115.sql:
\pset tuples_only on
\pset format unaligned
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='10s';
SELECT json_build_object('section','context','at',now(),'tenant','local','read_only',current_setting('transaction_read_only'));
SELECT json_build_object('section','shopee_batch_detail','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT b.id,b.status,b.started_at,b.finished_at,b.metadata#>>'{execution,error}' AS error,
 b.metadata#>'{execution,stores}' AS stores,b.metadata#>'{execution,triage}' AS triage,
 b.metadata#>'{execution,affiliateFailures}' AS affiliate_failures,
 (SELECT count(*)::int FROM garimpa.capture_run r WHERE r.tenant_id=b.tenant_id AND r.parameters->>'operationBatchId'=b.id::text) AS run_count,
 (SELECT count(distinct o.product_id)::int FROM garimpa.price_observation o JOIN garimpa.capture_run r ON r.tenant_id=o.tenant_id AND r.id=o.capture_run_id
  WHERE r.tenant_id=b.tenant_id AND r.parameters->>'operationBatchId'=b.id::text) AS distinct_products
 FROM garimpa.capture_batch b WHERE b.tenant_id='local' AND b.id='488698fe-32ea-48cc-9828-7b8dfc63ac24'
) t;
SELECT json_build_object('section','today_browser_products_current','rows',coalesce(json_agg(t),'[]')) FROM (
 WITH received AS (
  SELECT distinct r.tenant_id,item.id FROM garimpa.extension_capture_receipt r
  CROSS JOIN LATERAL jsonb_array_elements_text(r.result->'productIds') item(id)
  WHERE r.tenant_id='local' AND r.created_at>=('2026-11-15'::timestamp AT TIME ZONE 'America/Sao_Paulo')
 )
 SELECT p.marketplace,count(*)::int AS distinct_products,
 count(*) filter(where EXISTS(SELECT 1 FROM garimpa.curation_attribute_assessment a WHERE a.tenant_id=p.tenant_id AND a.product_id=p.id))::int AS has_assessment,
 count(*) filter(where EXISTS(SELECT 1 FROM garimpa.curation_attribute_job j WHERE j.tenant_id=p.tenant_id AND j.product_id=p.id AND j.status IN ('running','queued')))::int AS with_active_job,
 count(*) filter(where EXISTS(SELECT 1 FROM garimpa.curation_attribute_job j WHERE j.tenant_id=p.tenant_id AND j.product_id=p.id AND j.status='reconciliation'))::int AS with_uncertain_job,
 count(*) filter(where c.status='pending')::int AS catalog_pending
 FROM received r JOIN garimpa.product p ON p.tenant_id=r.tenant_id AND p.id=r.id
 LEFT JOIN garimpa.product_curation c ON c.tenant_id=p.tenant_id AND c.product_id=p.id
 GROUP BY p.marketplace ORDER BY p.marketplace
) t;
SELECT json_build_object('section','recent_twenty_shopee_runs','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT mode,count(*)::int AS runs,min(started_at) AS oldest,max(started_at) AS newest FROM (
 SELECT parameters->>'captureMode' AS mode,started_at FROM garimpa.capture_run WHERE tenant_id='local' AND marketplace='shopee'
 ORDER BY started_at DESC LIMIT 20
 ) latest GROUP BY mode
) t;
SELECT json_build_object('section','database_visibility','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT table_name,column_name FROM information_schema.columns WHERE table_schema='garimpa'
 AND table_name IN ('affiliate_monitoring_policy','monitoring_policy','curation_policy_v2','discovery_policy','pauta_selection_cache','recommendation_edition')
 ORDER BY table_name,ordinal_position
) t;
COMMIT;

sql_used.garimpa-audit-controls-20261115.sql:
\pset tuples_only on
\pset format unaligned
BEGIN READ ONLY;
SET LOCAL statement_timeout='8s';
SELECT json_build_object('section','context','at',now(),'tenant','local','read_only',current_setting('transaction_read_only'));
SELECT json_build_object('section','monitoring_policies','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT p.marketplace,p.enabled FROM garimpa.affiliate_monitoring_policy p
 JOIN garimpa.affiliate_account a ON a.id=p.affiliate_id WHERE a.tenant_id='local' ORDER BY p.marketplace
) t;
SELECT json_build_object('section','discovery_policies','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT marketplace,enabled FROM garimpa.editorial_discovery_policy WHERE tenant_id='local' ORDER BY marketplace
) t;
SELECT json_build_object('section','affiliate_configuration','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT c.marketplace,c.status FROM garimpa.affiliate_marketplace_config c
 JOIN garimpa.affiliate_account a ON a.id=c.affiliate_id WHERE a.tenant_id='local' ORDER BY c.marketplace
) t;
SELECT json_build_object('section','shopee_batch_publication_now','rows',coalesce(json_agg(t),'[]')) FROM (
 WITH products AS (
 SELECT distinct o.tenant_id,o.product_id FROM garimpa.price_observation o JOIN garimpa.capture_run r
 ON r.tenant_id=o.tenant_id AND r.id=o.capture_run_id
 WHERE r.tenant_id='local' AND r.parameters->>'operationBatchId'='488698fe-32ea-48cc-9828-7b8dfc63ac24'
 )
 SELECT count(*)::int AS products,
 count(*) filter(where EXISTS(SELECT 1 FROM garimpa.publication pub WHERE pub.tenant_id=p.tenant_id AND pub.product_id=p.product_id AND pub.channel='web' AND pub.status='active' AND nullif(btrim(pub.affiliate_url),'') IS NOT NULL))::int AS with_active_link,
 count(*) filter(where EXISTS(SELECT 1 FROM garimpa.curation_attribute_job j WHERE j.tenant_id=p.tenant_id AND j.product_id=p.product_id AND j.status='reconciliation'))::int AS uncertain_evaluation,
 count(*) filter(where EXISTS(SELECT 1 FROM garimpa.curation_attribute_assessment a WHERE a.tenant_id=p.tenant_id AND a.product_id=p.product_id))::int AS has_assessment
 FROM products p
) t;
SELECT json_build_object('section','rollout','commercial_ready',garimpa.commercial_rollout_ready());
SELECT json_build_object('section','pauta_cached','rows',coalesce(json_agg(t),'[]')) FROM (
 SELECT channel,active,offer_count,prepared_at,offer_valid_until FROM garimpa.pauta_selection_cache WHERE tenant_id='local' ORDER BY channel
) t;
COMMIT;
